function heightChecker(heights) {
  const count = new Array(101).fill(0);
  for (const h of heights) count[h]++;              // heights are 1..100
  let mismatches = 0, h = 1;
  for (const actual of heights) {
    while (count[h] === 0) h++;                     // the next height in sorted order
    if (actual !== h) mismatches++;
    count[h]--;
  }
  return mismatches;
}

def height_checker(heights):
    count = [0] * 101
    for h in heights:
        count[h] += 1                     # heights are 1..100
    mismatches, h = 0, 1
    for actual in heights:
        while count[h] == 0:              # the next height in sorted order
            h += 1
        if actual != h:
            mismatches += 1
        count[h] -= 1
    return mismatches

